const body = $input.first().json.body || $input.first().json;
const title = body.title || '';
const slug = body.slug || '';
const summary = (body.summary || body.excerpt || '').substring(0, 200);
const rating = body.rating || '';
const price = body.price || '';
const featuredImage = body.featuredImage || 'https://placehold.co/1080x1920/FF6B00/ffffff?text=KaoShop';
const affiliateUrl = body.affiliateUrl || '';
const articleUrl = 'https://kaoshop-omega.vercel.app/article/' + slug;

return [{ json: { title, slug, articleUrl, featuredImage, affiliateUrl, summary, rating, price } }];

const data = $input.first().json;

const prompt = `สร้าง TikTok caption จากสินค้าต่อไปนี้:\n\nชื่อสินค้า: ${data.title}\nสรุป: ${data.summary || ''}\nคะแนน: ${data.rating}/5\nราคา: ฿${data.price || 'ไม่ระบุ'}\nลิงก์บทความ: ${data.articleUrl}\n\nส่งกลับเป็น JSON เท่านั้น:\n{\n  "caption": "caption TikTok ภาษาไทย กระชับ 50-80 คำ เน้น hook แรก น่าสนใจ + hashtag 5-8 ตัวท้าย รวม #KaoShop #รีวิวสินค้า"\n}`;

const openAIPayload = {
  model: 'gpt-4o-mini',
  response_format: { type: 'json_object' },
  messages: [
    {
      role: 'system',
      content: 'คุณเป็น TikTok Content Creator ผู้เชี่ยวชาญ content ภาษาไทย ตอบกลับเป็น JSON เท่านั้น'
    },
    {
      role: 'user',
      content: prompt
    }
  ]
};

return [{ json: { openAIPayload, ...data } }];

const gpt = $input.first().json;
const prepData = $('เตรียม Content').first().json;

let caption = '';

try {
  const content = gpt.choices[0].message.content;
  const parsed = JSON.parse(content);
  caption = parsed.caption || '';
} catch(e) {
  caption = '🛒 ' + prepData.title + (prepData.rating ? ' ⭐' + prepData.rating + '/5' : '') + ' #KaoShop #รีวิวสินค้า #ช้อปออนไลน์';
}

const tiktokPayload = {
  post_info: {
    title: caption,
    privacy_level: 'SELF_ONLY',
    disable_duet: false,
    disable_comment: false,
    disable_stitch: false
  },
  source_info: {
    source: 'PULL_FROM_URL',
    photo_cover_index: 0,
    photo_images: [prepData.featuredImage]
  },
  post_mode: 'DIRECT_POST',
  media_type: 'PHOTO'
};

return [{ json: { ...prepData, caption, tiktokPayload } }];
